class Solution {
  public int[] sortByReflection(int[] nums) {
    Integer[] boxed = new Integer[nums.length];
    for (int i = 0; i < nums.length; i++) boxed[i] = nums[i];
    Arrays.sort(
        boxed,
        (a, b) -> {
          int ra = reflect(a), rb = reflect(b);
          return ra != rb ? Integer.compare(ra, rb) : Integer.compare(a, b);
        });
    for (int i = 0; i < nums.length; i++) nums[i] = boxed[i];
    return nums;
  }

  private int reflect(int x) {
    return Integer.parseInt(new StringBuilder(Integer.toBinaryString(x)).reverse().toString(), 2);
  }
}
